<script>document.addEventListener('click',event=>{const add=event.target.closest('[data-add]');if(add){const target=document.getElementById(add.dataset.add),i=target.children.length,row=document.createElement('div');row.className='repeat-row grid gap-2 md:grid-cols-4';row.innerHTML=add.dataset.add==='fees'?`<input class="input" name="fee_items[${i}][name]" placeholder="Nama biaya" required><input class="input" type="number" min="0" name="fee_items[${i}][male]" placeholder="Putra" required><input class="input" type="number" min="0" name="fee_items[${i}][female]" placeholder="Putri" required><button type="button" class="btn btn-danger" data-remove>Hapus</button>`:add.dataset.add==='schedules'?`<input class="input" name="schedule_items[${i}][title]" placeholder="Judul" required><input class="input" type="datetime-local" name="schedule_items[${i}][scheduled_at]"><input class="input" name="schedule_items[${i}][description]" placeholder="Deskripsi"><button type="button" class="btn btn-danger" data-remove>Hapus</button>`:`<input class="input" name="document_requirements[${i}][name]" placeholder="Nama" required><input class="input" name="document_requirements[${i}][code]" placeholder="kode" required><select class="input" name="document_requirements[${i}][channel]"><option value="both">Online & offline</option><option value="online">Online</option><option value="offline">Offline</option></select><label><input type="checkbox" name="document_requirements[${i}][is_required]" value="1"> Wajib</label><label><input type="checkbox" name="document_requirements[${i}][is_active]" value="1" checked> Aktif</label><button type="button" class="btn btn-danger" data-remove>Hapus</button>`;target.append(row)}if(event.target.closest('[data-remove]'))event.target.closest('.repeat-row').remove()})</script></x-layouts.app>
